import {showOrdinanceAnalysis} from './ordinance-analysis-ui.js?v=civic-reward-fidelity-1';
const number=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:1});
export function transportationBriefing(c){
 const s=c.stats,issues=[],add=(title,text,action,layer,tool)=>issues.push({title,text,action,layer,tool});
 const homes=c.tiles.filter(t=>t.type==='residential'&&t.level&&t.commuters>0),disconnected=homes.filter(t=>!t.access),unserved=homes.filter(t=>t.unemployed>.01).sort((a,b)=>b.unemployed-a.unemployed||a.y-b.y||a.x-b.x),busy=c.tiles.filter(t=>t.traffic>40||t.highwayTraffic>160).sort((a,b)=>Math.max(b.traffic/40||0,b.highwayTraffic/160||0)-Math.max(a.traffic/40||0,a.highwayTraffic/160||0));
 if(s.transitStrike)add('Restore transit service','Transit workers are on strike. Restore transit funding to 100% and run one month.','funding');
 if(c.finance.roadCondition<=20)add('Repair the road network','Road condition is too low for normal access. Restore road maintenance in Budget and allow time for repairs.','budget');
 else if(c.finance.roadCondition<80)add('Road maintenance is deteriorating',`Road condition is ${number(c.finance.roadCondition)}%. Review road funding before more connections become unusable.`,'budget');
 if(!s.population)add('Connect your first neighborhood','Homes need usable routes to workplaces. Plan roads and powered residential and employment zoning together.','map','zones','road');
 if(disconnected.length)add('Homes lack usable transport',`${disconnected.length} occupied residential tiles have no usable transport access. Check roads near homes and jobs, or stations and a connected rail route.`,'map','traffic','road');
 if(s.jobs<s.commuters)add('The city needs more workplaces',`There are ${number(s.jobs)} job positions for ${number(s.commuters)} potential workers. Transport alone cannot fill a citywide shortage of positions. Support commercial or industrial development.`,'map','zones','industrial');
 if(s.unemployed>.01)add('Workers are still without reachable jobs',`${number(s.unemployed)} workers did not find a reachable available position. Route connections, limited job capacity and competition between neighborhoods all matter. Inspect the homes below.`,'map','traffic');
 if(busy.length)add('Relieve busy corridors',`${busy.length} surface tiles have congested roads or highways. Consider connected alternate routes, bus stops near homes, or rail stations near homes and workplaces.`,'map','traffic','busStop');
 if(s.busStops>s.activeBusStops)add('Check inactive bus stops',`${s.busStops-s.activeBusStops} bus stops are not operating. Check their road connection, road condition, transit funding and strike status.`,'map','transit','busStop');
 if(s.stations>s.activeStations)add('Check inactive rail stations',`${s.stations-s.activeStations} rail or subway stations are not operating. Inspect their tracks, transit funding, equipment condition and strike status.`,'map','rail','trainStation');
 if(c.transport.condition<80&&!s.transitStrike)add('Maintain transit equipment',`Transit condition is ${number(c.transport.condition)}%. Review funding and allow time for equipment to recover.`,'funding');
 if(!issues.length)add('Keep connections ahead of growth','Current workers can reach available jobs and no congested corridors were found. Watch new neighborhoods as they develop.','map','traffic');
 return{issues,unserved:unserved.slice(0,12),busy:busy.slice(0,12),disconnected:disconnected.length};
}
export function showTransportationAdvisor(ui,back){const c=ui.city(),s=c.stats,b=transportationBriefing(c);
 ui.dialog('Moe Biehl',`<div class="civic-advisor-header"><img src="assets/moe-advisor.png" width="192" height="192" alt=""><div><p class="eyebrow">Transportation advisor</p><h3>Help your city get moving</h3><p>Connect workers to available jobs, then keep busy corridors and transit equipment working.</p></div></div><dl class="civic-advisor-facts"><div><dt>Workers / jobs filled</dt><dd>${number(s.commuters)} / ${number(s.commuters-s.unemployed)}</dd></div><div><dt>Bus / rail riders</dt><dd>${number(s.busRiders)} / ${number(s.trainRiders)}</dd></div><div><dt>Road / transit condition</dt><dd>${number(c.finance.roadCondition)}% / ${number(c.transport.condition)}%</dd></div></dl>${b.issues.map((issue,i)=>`<article class="civic-advisor-issue"><h3>${issue.title}</h3><p>${issue.text}</p><button data-moe-action="${i}">${issue.action==='budget'?'Review road budget':issue.action==='funding'?'Review transit funding':'View map'}</button>${issue.tool?`<button data-moe-build="${i}">Plan ${issue.tool==='busStop'?'bus stop':issue.tool==='trainStation'?'train station':issue.tool==='industrial'?'industrial zoning':'road'}</button>`:''}</article>`).join('')}${[['Homes with unserved workers',b.unserved,'homes'],['Congested corridors',b.busy,'busy']].map(([title,rows,key])=>`<h3>${title}</h3><p>Up to 12 locations, ordered by ${key==='homes'?'unserved workers':'congestion'}.</p>${rows.length?rows.map((t,i)=>`<p>${t.x+1}, ${t.y+1} · ${key==='homes'?number(t.unemployed)+' workers without a job':number(t.traffic)+' road / '+number(t.highwayTraffic)+' highway traffic'} <button data-moe-${key}="${i}">Inspect location</button></p>`).join(''):'<p>No locations currently flagged.</p>'}`).join('')}<p class="fine">Advice describes the current simulation. Maps and planning shortcuts do not spend funds or advance time. Unemployment can reflect job shortages as well as disconnected routes.</p><button id="moePolicies">Compare transportation ordinances</button><button id="moeBack">Back to transport</button>`);
 document.querySelector('#moeBack').onclick=back;
 document.querySelector('#moePolicies').onclick=()=>showOrdinanceAnalysis(ui,'transport',()=>showTransportationAdvisor(ui,back));
 document.querySelectorAll('[data-moe-action]').forEach(button=>button.onclick=()=>{const issue=b.issues[Number(button.dataset.moeAction)];if(issue.action==='budget')ui.budget();else if(issue.action==='funding')back();else{ui.setLayer(issue.layer);ui.close();}});
 document.querySelectorAll('[data-moe-build]').forEach(button=>button.onclick=()=>{ui.setTool(b.issues[Number(button.dataset.moeBuild)].tool);ui.close();});
 for(const key of ['homes','busy'])document.querySelectorAll('[data-moe-'+key+']').forEach(button=>button.onclick=()=>{const t=(key==='homes'?b.unserved:b.busy)[Number(button.dataset[key==='homes'?'moeHomes':'moeBusy'])];ui.locate({x:t.x,y:t.y});});
}
